-- GENERATED by `wfj generate` from data/gossip/gossip-f9.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["f90326be822bcf2b"] = { "Tutto fatto! Le modifiche dovrebbero darci un po' di velocità in più, ma non credo che reggerà a troppi urti.", "." },
  ["f90d8864497d3bd2"] = { "Ai tuoi ordini!", "." },
  ["f90f34dd10fe5438"] = { "Buongiorno, {class}. Cosa desideri?", "." },
  ["f912b74482bab818"] = { "No, {class}, non è tutto. Le forze d'élite dell'avversario sono comandate dai quattro comandanti della base. Se riuscirai a sferrare un colpo rapido e fatale ai loro comandanti, la linea d'élite vacillerà. I loro ranghi si ridurranno a nulla!\n\nMa sta' in guardia, soldato: comandanti e tenenti non vanno presi alla leggera né sottovalutati. Si sono guadagnati quei gradi...", "." },
  ["f92045716a810ada"] = { "Tu non sei mica <un/una> <guerriero/guerriera>... Ma va', non dureresti neanche un giorno col mio addestramento!\n\n<Un/Una> {class} che si crede <un/una> <guerriero/guerriera>. Ah!", "." },
  ["f9228c6635510031"] = { "Il vento ti viene incontro veloce dall'orizzonte; la terra è salda sotto i tuoi piedi; e il tuo spirito è già scaldato dal fuoco: direi che è giunto il momento di conoscere la purezza dell'acqua.\n\nIl tuo cammino ti ha portato fin qui, e il tuo spirito ti darà la forza di andare ancora più lontano. Ma il primo passo spetta a te.", "." },
  ["f92b72b3ff55d142"] = { "Grifoni, eh? Non mi sono mai piaciute quelle bestie, ma ognuno ha i suoi gusti.\n\nTrovi Dungar Longdrink sui bastioni del ⟦Trade District=Quartiere del Commercio⟧.", "." },
  ["f931475cf86a9005"] = { "Guarda là! Qualcuno sta combattendo contro Mushgog!", "." },
  ["f939040ac50ea81d"] = { "Rilassati, l'⟦Alliance=Alleanza⟧ è molto indietro rispetto a noi, mon. Noi qui abbiamo finito con le raccolte, e proprio ora si danno gli ultimi ritocchi. Quando quelli finiranno là nella loro ⟦Ironforge=Forgiardente⟧, allora penseremo a spostare tutta questa roba a ⟦Silithus=Silitus⟧. Fino ad allora, aspetta con calma e magari fatti una pescata.", "." },
  ["f941b72266268d1e"] = { "E a tagliare il traguardo è l'auto degli gnomi! Vincono gli gnomi!", "." },
  ["f942cc351a1c711a"] = { "Non vale la pena rispondere.", "." },
  ["f94ba3aced283379"] = { "Le ⟦Silverwing Sentinels=Sentinelle Alargentea⟧ saranno in debito con te, {class}. Troverai Elfarran, il nostro maestro di battaglia, nel Castello di ⟦Stormwind=Roccavento⟧, presente all'udienza del re bambino. Che la Dea vegli su di te!", "." },
  ["f952964e1692d7f4"] = { "Ora resta un solo passo per liberarci della minaccia dello Scortica Anime...", "." },
  ["f954053dee41e01b"] = { "Abbiamo tutti i lingotti di rame che ci servono. Grazie per l'aiuto, {class}. Potresti dare una mano con gli altri materiali che si stanno raccogliendo qui.", "." },
  ["f958144a90778e7c"] = { "Io non ti do problemi, capo.", "." },
  ["f95bd285e3187408"] = { "Figli della Follia, vi libero su questo mondo!", "." },
  ["f96595a6d6c9038d"] = { "Che Elune sia con te, {class}.", "." },
  ["f96ac5f7d53fae38"] = { "{name}, ho di nuovo bisogno del tuo aiuto.", "." },
  ["f96c7527f82d8e85"] = { "Mmm, a quanto pare Keever ha bisogno di una nuova cavia. Se quello sciocco di Abernathy continua a prendersi le cavie di Keever, Keever dovrà fare due chiacchiere con lui.", "." },
  ["f9706fafc56b9df1"] = { "Ahimè, ho chiacchierato abbastanza. Cerca la mia apprendista Ayessa Dawnsinger nel porto di Valanaar, se ti capita di passare da quelle parti. Lei sente ancora il canto, anche se debolmente. La vecchiaia mi pesa e gran parte del mio potere mi ha abbandonato. Ayessa rappresenta il futuro del nostro popolo e il cammino che ora dobbiamo percorrere per sopravvivere. Tocca a lei e ai giovani skyborne come te portare avanti le speranze del nostro popolo.", "." },
  ["f97295bd13f0746e"] = { "Hai la stoffa per eccellere nella caccia? Beh, <ragazzo/ragazza> <mio/mia>, solo il tempo lo dirà. Ma non metterti a tirare alle mele sulla testa della gente finché non hai parlato con Regnus, laggiù nell'Hall of Arms.", "." },
  ["f976ce3f5aeac77e"] = { "Aspetta! Sembra che la nostra vedetta abbia avvistato qualcosa.", "." },
  ["f9804223306be7ec"] = { "Delizioso!", "." },
  ["f9824c44b2ba7432"] = { "Dov'è l'istruttore di Estrazione?", "." },
  ["f9867c6f18b14f28"] = { "Lo dico alla mamma!", "." },
  ["f98b9cab8696d6cb"] = { "L'ostessa Pala ti aiuterà a far riposare corpo e spirito. La trovi nell'edificio appena a sud della banca, sul terrazzo inferiore.", "." },
  ["f98cb116da27609a"] = { "Berte! Evalyn! Si fa buio. Venite dentro.", "." },
  ["f992bfc86a355129"] = { "Un'anima appassionata come me, eh? Beh, aspetta e vedrai: faremo di te una testa di bullone in un attimo!", "." },
  ["f996b0f943ae6a89"] = { "Altro che investimento sbagliato!\n\nIl libro oscuro di incantesimi di Lord Valthalak ci ha fruttato un bel gruzzolo al mercato nero. Peccato che lui non abbia preso affatto bene il furto dei suoi averi. Quel fetente ci ha fatto pagare anche dopo essere morto da mesi!", "." },
  ["f997bd20b6fc294c"] = { "Che maledetto spreco!", "." },
  ["f9a28c27da4e1ac8"] = { "Soldati dei Piccatonante, venite in mio aiuto! Il segnale deve essere piantato.", "." },
  ["f9af619b18905d5e"] = { "Mmm... Adoro la mia deliziosa birra scura di ⟦Southshore=Riva del Sud⟧.", "." },
  ["f9b15e4ac8aae775"] = { "Le professioni si dividono in due categorie principali: primarie e secondarie.\n\nPuoi avere al massimo due professioni primarie alla volta. Puoi abbandonare la tua abilità in una professione primaria in qualsiasi momento; tuttavia, tutto il sapere che hai accumulato andrà perduto. Se decidi di tornare alla tua professione originale, dovrai addestrarti di nuovo dalle basi e cercare le ricette che avevi già acquisito per riprendere familiarità con esse.\n\nLe professioni secondarie non hanno un simile limite. Queste abilità tendono a favorire l'autosufficienza per le esigenze di sopravvivenza di base. Puoi apprenderne una, alcune o tutte, ma potresti trovare meno occasioni per ricavarne un profitto.", "." },
  ["f9b944029a5e6e86"] = { "Lo spirito di Kuramaa è eterno, e si manifesterà di nuovo quando ce ne sarà bisogno. La sua maschera è una fonte di grande potere e si rivelerà preziosissima per il rituale che dobbiamo compiere.", "." },
  ["f9bdbfca9ee34c2f"] = { "Mmm... gli unici incantatori che conosco da queste parti lavorano a ⟦Stormwind=Roccavento⟧. Perché non chiedi a una delle guardie lassù a ⟦Stormwind=Roccavento⟧?", "." },
  ["f9ca28e362067b7d"] = { "Se è mio destino cadere, allora con il mio ultimo respiro ti porterò con me!", "." },
  ["f9d1edca4f1d9625"] = { "Capisco, amico mio. Troverò qualcuno che aiuti il tuo padrone. Torna da lui ora, o almeno resta nei paraggi.", "." },
  ["f9ddceae4d3bcd06"] = { "I servitori di Sul banchetteranno con i tuoi resti.", "." },
  ["f9e06a28e016a245"] = { "Noi non tanto sicuri paladini sicuri da toccare, ma loro in ⟦War Quarter=Quartiere della Guerra⟧ in grande edificio.", "." },
  ["f9e41e017c1ae5e2"] = { "Gli ippogrifi di Vesprystus ti porteranno rapidamente a destinazione. Cercalo a ⟦Rut'theran Village=Rut'theran⟧, oltre il portale che si trova nella parte occidentale di Darnassus.", "." },
  ["f9e611b0d01e695e"] = { "{name}, i miei doveri sono compiuti e ora prenderò congedo. Buona fortuna, <amico/amica> <mio/mia>, e ricorda di mantenere in funzione la Campana, la Ruota e la Candela!", "." },
  ["f9ed25172b894337"] = { "Calma, {race}. Quello che devi uccidere è già morto. Ucciderlo di nuovo non servirà a niente. Ci sono pochissimi modi per distruggere davvero un lich, e nessuno di questi è alla portata tua o mia. Ecco perché ho un piano. Un piano che avrà un impatto molto evidente e reale sul Culto.", "." },
  ["f9f53221afb85029"] = { "%s sospira.", "." },
  ["f9facd6e7442e0fb"] = { "Nel caso non fosse ovvio, non sono qui per curare i rapporti con la clientela.", "." },
  ["f9ff5bd1f2542a21"] = { "%s comincia a frugare tra i distintivi dei difensori caduti di Stromgarde...", "." },
})
